const usersInGroup = `-- name: UsersInGroup :many
SELECT DISTINCT u.id, u.auth_service, u.auth_data, u.email, u.email_verified, u.display_name, u.created_at, u.updated_at, u.last_login_at, u.is_admin, u.is_bot, u.username, u.directory_role, u.deactivated_at, u.avatar_id, u.avatar_from_directory, u.directory_photo, u.timezone, u.show_last_seen, u.last_seen_at, u.status_emoji, u.status_text, u.status_expires_at, u.recent_statuses, u.username_from_directory, u.terms_accepted_id, u.share_read_receipts, u.guest_link_id, u.ooo_from, u.ooo_until, u.ooo_message, u.language FROM users u JOIN user_groups g ON g.user_id = u.id
WHERE lower(g.group_name) = lower($1) AND u.deactivated_at IS NULL
`

func (q *Queries) UsersInGroup(ctx context.Context, groupName string) ([]User, error) {
	rows, err := q.db.Query(ctx, usersInGroup, groupName)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []User
	for rows.Next() {
		var i User
		if err := rows.Scan(
			&i.ID,
			&i.AuthService,
			&i.AuthData,
			&i.Email,
			&i.EmailVerified,
			&i.DisplayName,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.LastLoginAt,
			&i.IsAdmin,
			&i.IsBot,
			&i.Username,
			&i.DirectoryRole,
			&i.DeactivatedAt,
			&i.AvatarID,
			&i.AvatarFromDirectory,
			&i.DirectoryPhoto,
			&i.Timezone,
			&i.ShowLastSeen,
			&i.LastSeenAt,
			&i.StatusEmoji,
			&i.StatusText,
			&i.StatusExpiresAt,
			&i.RecentStatuses,
			&i.UsernameFromDirectory,
			&i.TermsAcceptedID,
			&i.ShareReadReceipts,
			&i.GuestLinkID,
			&i.OooFrom,
			&i.OooUntil,
			&i.OooMessage,
			&i.Language,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

